61	/** TLS credential reload config. **/
62	struct grpc_tls_credential_reload_config
63	    : public grpc_core::RefCounted<grpc_tls_credential_reload_config> {
64	 public:
65	  grpc_tls_credential_reload_config(
66	      const void* config_user_data,
67	      int (*schedule)(void* config_user_data,
68	                      grpc_tls_credential_reload_arg* arg),
69	      void (*cancel)(void* config_user_data,
70	                     grpc_tls_credential_reload_arg* arg),
71	      void (*destruct)(void* config_user_data));
72	  ~grpc_tls_credential_reload_config();
73	
74	  void* context() const { return context_; }
75	  void set_context(void* context) { context_ = context; }
76	
77	  int Schedule(grpc_tls_credential_reload_arg* arg) const {
78	    if (schedule_ == nullptr) {
79	      gpr_log(GPR_ERROR, "schedule API is nullptr");
80	      if (arg != nullptr) {
81	        arg->status = GRPC_SSL_CERTIFICATE_CONFIG_RELOAD_FAIL;
82	        arg->error_details =
83	            gpr_strdup("schedule API in credential reload config is nullptr");
84	      }
85	      return 1;
86	    }
87	    if (arg != nullptr) {
88	      arg->config = const_cast<grpc_tls_credential_reload_config*>(this);
89	    }
90	    return schedule_(config_user_data_, arg);
91	  }
92	  void Cancel(grpc_tls_credential_reload_arg* arg) const {
93	    if (cancel_ == nullptr) {
94	      gpr_log(GPR_ERROR, "cancel API is nullptr.");
95	      if (arg != nullptr) {
96	        arg->status = GRPC_SSL_CERTIFICATE_CONFIG_RELOAD_FAIL;
97	        arg->error_details =
98	            gpr_strdup("cancel API in credential reload config is nullptr");
99	      }
100	      return;
101	    }
102	    if (arg != nullptr) {
103	      arg->config = const_cast<grpc_tls_credential_reload_config*>(this);
104	    }
105	    cancel_(config_user_data_, arg);
106	  }
107	
108	 private:
109	  /** This is a pointer to the wrapped language implementation of
110	   * grpc_tls_credential_reload_config. It is necessary to implement the C
111	   * schedule and cancel functions, given the schedule or cancel function in a
112	   * wrapped language. **/
113	  void* context_ = nullptr;
114	  /** config-specific, read-only user data that works for all channels created
115	     with a credential using the config. */
116	  void* config_user_data_;
117	  /** callback function for invoking credential reload API. The implementation
118	     of this method has to be non-blocking, but can be performed synchronously
119	     or asynchronously.
120	     If processing occurs synchronously, it populates \a arg->key_materials, \a
121	     arg->status, and \a arg->error_details and returns zero.
122	     If processing occurs asynchronously, it returns a non-zero value.
123	     Application then invokes \a arg->cb when processing is completed. Note that
124	     \a arg->cb cannot be invoked before \a schedule returns.
125	  */
126	  int (*schedule_)(void* config_user_data, grpc_tls_credential_reload_arg* arg);
127	  /** callback function for cancelling a credential reload request scheduled via
128	     an asynchronous \a schedule. \a arg is used to pinpoint an exact reloading
129	     request to be cancelled, and the operation may not have any effect if the
130	     request has already been processed. */
131	  void (*cancel_)(void* config_user_data, grpc_tls_credential_reload_arg* arg);
132	  /** callback function for cleaning up any data associated with credential
133	     reload config. */
134	  void (*destruct_)(void* config_user_data);
135	};
